with filtered as (select *, month(event_time) as event_time_month, coalesce(page, 'OTHER') as resolved_page from web_events where event_time >= '2023-05-13'), with_prev as (select *, lag(event_time) over (partition by event_type order by event_time, id) as prev_event_time from filtered), gaps as (select *, case when prev_event_time is null or event_time > prev_event_time + interval 60 days then 1 else 0 end as is_new_burst from with_prev), islands as (select *, sum(is_new_burst) over (partition by event_type order by event_time, id rows between unbounded preceding and current row) as island_id from gaps) select island_id, round(avg(island_id), 2) as avg_island_id, sort_array(collect_set(event_type)) as event_type_list from islands group by island_id
